<?php get_header(); ?><section class="glass content-panel"><div class="eyebrow">ACTUALIDAD</div><h1><?php echo is_home() ? 'Noticias' : esc_html(get_the_archive_title()); ?></h1>
<?php if (have_posts()): ?><div class="post-grid"><?php while(have_posts()):the_post(); ?><article <?php post_class('post-card'); ?>><a href="<?php the_permalink(); ?>"><?php if (has_post_thumbnail()) the_post_thumbnail('medium_large', ['class'=>'post-thumb']); ?><h2><?php the_title(); ?></h2></a><p><?php echo esc_html(wp_trim_words(get_the_excerpt(), 27)); ?></p><small><?php echo esc_html(get_the_date()); ?></small></article><?php endwhile; ?></div><?php the_posts_pagination(); else: ?><p>Por ahora no hay noticias publicadas.</p><?php endif; ?></section><?php get_footer(); ?>
